    if (video.paused) {
      video.play();
    }
    playing = !video.paused;
  }
  const title = document.querySelector('h1.ytd-watch-metadata, #title h1, h1 yt-formatted-string')?.textContent?.trim() || document.title;
  const channel = document.querySelector('#channel-name, ytd-channel-name, #owner #text a')?.textContent?.trim();
  const time = video ? { currentTime: video.currentTime, duration: video.duration, paused: video.paused } : null;
  return { title, channel, url: window.location.href, time, playing };
});

