await tool.navigate({ tabId, url: "https://www.citationmachine.net/" });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

const pageData = await browserjs(tabId, () => {
  const footer = document.querySelector('footer');
  const main = document.querySelector('main');
  return {
    footerText: footer?.innerText,
    links: Array.from(document.querySelectorAll('footer a, nav a')).map(a => ({
      text: a.textContent?.trim(),
      href: a.href
    }))
  };
});
console.log("Footer text:", pageData.footerText);
console.log("Footer/Nav links:", JSON.stringify(pageData.links.filter(l => l.href.includes('apa') || l.href.includes('harvard') || l.href.includes('mla')), null, 2));

