const tabId = 103795240;
await tool.navigate({ tabId, url: "https://www.citationmachine.net/apa" });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

const footerLinks = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a')).filter(a => {
    const text = a.textContent?.trim() || "";
    return text === "APA" || text === "Harvard Referencing" || text === "MLA" || text === "Chicago Style";
  }).map(a => ({
    text: a.textContent?.trim(),
    href: a.href,
    visible: a.offsetParent !== null
  }));
  return links;
});
console.log("Footer style links on /apa:", JSON.stringify(footerLinks, null, 2));

